import '@servicenow/sdk/global'
import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'
import { Flow, Subflow, trigger, wfa } from '@servicenow/sdk/automation'
import { ActionDefinition } from '@servicenow/sdk/automation'

// Action definition for testing action output datapills
export const actionDef = ActionDefinition({
    $id: Now.ID['flow-action-def'],
    name: 'Flow Action Sample',
    annotation: 'Action for flow datapill testing',
    description: 'Test action definition',
    inputs: {
        recordId: StringColumn({
            label: 'Record ID',
            mandatory: true,
        }),
        isActive: BooleanColumn({
            label: 'Is Active',
            mandatory: true,
        }),
        description: StringColumn({
            label: 'Description',
            mandatory: true,
        }),
    },
    outputs: {
        result: StringColumn({
            label: 'Result',
            mandatory: true,
        }),
        status: BooleanColumn({
            label: 'Status',
            mandatory: true,
        }),
    },
})

// Subflow definition for testing subflow output datapills
export const subflowDef = Subflow(
    {
        $id: Now.ID['flow-subflow-def'],
        name: 'Flow Subflow Sample',
        annotation: 'Subflow for flow datapill testing',
        description: 'Test subflow definition',
        inputs: {
            userId: StringColumn({
                label: 'User ID',
                mandatory: true,
            }),
            priority: StringColumn({
                label: 'Priority',
                mandatory: true,
            }),
        },
        outputs: {
            processedResult: StringColumn({
                label: 'Processed Result',
                mandatory: true,
            }),
            completionStatus: BooleanColumn({
                label: 'Completion Status',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // Internal action in subflow
        wfa.action(
            actionDef,
            {
                $id: Now.ID['subflow-internal-action'],
                uuid: 'a1a1a1a1-b2b2-4c3c-8d4d-e5e5e5e5e5e5',
            },
            {
                recordId: wfa.dataPill(params.inputs.userId, 'string'),
                isActive: true,
                description: `Processing user ${wfa.dataPill(params.inputs.userId, 'string')} with priority ${wfa.dataPill(params.inputs.priority, 'string')}`,
            }
        )
    }
)

// Main Flow with Trigger and comprehensive datapill examples
Flow(
    {
        $id: Now.ID['flow-datapills-example'],
        name: 'Flow Datapills Example',
        description: 'Flow with trigger datapills, flow variables, action outputs, and subflow outputs',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            processType: StringColumn({
                label: 'Process Type',
                mandatory: true,
            }),
            maxRetries: StringColumn({
                label: 'Max Retries',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['flow-trigger-datapills'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // First action using trigger datapills
        const action_1 = wfa.action(
            actionDef,
            {
                $id: Now.ID['action-with-trigger-pills'],
                uuid: '11111111-2222-3333-4444-555555555555',
            },
            {
                recordId: 'params.trigger.current.sys_id',
                isActive: true,
                description: `Triggered by ${wfa.dataPill(params.trigger.current.sys_id, 'string')} on table ${wfa.dataPill(params.trigger.table_name, 'string')}`,
            }
        )

        // Second action using flow variables
        const action_2 = wfa.action(
            actionDef,
            {
                $id: Now.ID['action-with-flow-vars'],
                uuid: '22222222-3333-4444-5555-666666666666',
            },
            {
                recordId: wfa.dataPill(params.flowVariables.processType, 'string'),
                isActive: false,
                description: `Flow variable: ${wfa.dataPill(params.flowVariables.processType, 'string')}, retries: ${wfa.dataPill(params.flowVariables.maxRetries, 'string')}`,
            }
        )

        // Subflow instance using trigger and action datapills
        const subflow_1 = wfa.subflow(
            subflowDef,
            {
                $id: Now.ID['subflow-with-datapills'],
                uuid: '33333333-4444-5555-6666-777777777777',
            },
            {
                userId: 'params.trigger.current.sys_created_by',
                priority: wfa.dataPill(action_1.result, 'string'),
            }
        )

        // Third action using multiple datapill types: trigger, action outputs, and subflow outputs
        wfa.action(
            actionDef,
            {
                $id: Now.ID['action-with-mixed-pills'],
                uuid: '44444444-5555-6666-7777-888888888888',
            },
            {
                recordId: 'params.trigger.current.sys_id',
                isActive: wfa.dataPill(action_1.status, 'boolean'),
                description: `Mixed: trigger=${wfa.dataPill(params.trigger.current, 'string')}, action=${wfa.dataPill(action_2.result, 'string')}, subflow=${wfa.dataPill(subflow_1.processedResult, 'string')}, status=${wfa.dataPill(subflow_1.completionStatus, 'boolean')}`,
            }
        )
    }
)
